<?php
declare(strict_types=1);
require dirname(__DIR__,3).'/app/Core/TaskExecutor.php';
require dirname(__DIR__,3).'/app/Core/Database.php';
require dirname(__DIR__,3).'/app/Core/Crypto.php';
require dirname(__DIR__,3).'/app/Services/DeviceWorkspaceService.php';
require dirname(__DIR__,3).'/app/Services/TaskEnvelopeService.php';
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$server=rtrim((string)($argv[1]??getenv('DCP_SERVER_URL')?:''),'/');
$token=(string)(($argv[2]??'')?:getenv('DCP_DEVICE_TOKEN')?:'');
$workspaceOverride=(string)(($argv[3]??'')?:getenv('DCP_WORKSPACE')?:'');
if(!str_starts_with($server,'https://')&&!str_starts_with($server,'http://127.0.0.1')){fwrite(STDERR,"DCP server must use HTTPS (localhost is allowed for testing).\n");exit(2);}
if($token===''){fwrite(STDERR,"Device token is required.\n");exit(2);}
function api(string $url,string $token,?array $body=null):array{$ch=curl_init($url);$headers=['Authorization: Bearer '.$token,'Accept: application/json'];$opts=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>60,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2];if($body!==null){$headers[]='Content-Type: application/json';$opts[CURLOPT_HTTPHEADER]=$headers;$opts[CURLOPT_POST]=true;$opts[CURLOPT_POSTFIELDS]=json_encode($body,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}curl_setopt_array($ch,$opts);$raw=curl_exec($ch);$error=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($raw===false||$code<200||$code>=300)throw new RuntimeException('DCP API error '.$code.': '.($error?:substr((string)$raw,0,300)));$decoded=json_decode((string)$raw,true);if(!is_array($decoded))throw new RuntimeException('DCP API returned invalid JSON.');return $decoded;}
$identity=api($server.'/api/device/heartbeat',$token,[]);$deviceId=(string)($identity['device_id']??'');
if(!preg_match('/^[A-Za-z0-9_-]{1,80}$/',$deviceId)){fwrite(STDERR,"DCP server returned an invalid paired device identity.\n");exit(3);}
$config=require dirname(__DIR__,3).'/config/app.php';$db=Database::connect($config);Database::migrate($db);$crypto=new Crypto($config['key_file']);$envelopes=new TaskEnvelopeService($db,$crypto);$localKey=$envelopes->registerSigningKey($deviceId);$signedTransport=false;
try{$identity=api($server.'/api/device/signing-key',$token,['public_key'=>$localKey['public_key']]);$serverDeviceId=(string)($identity['server_device_id']??'');$serverPublic=base64_decode((string)($identity['server_public_key']??''),true);if(!preg_match('/^[A-Za-z0-9_-]{1,80}$/',$serverDeviceId)||$serverPublic===false||strlen($serverPublic)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES||!hash_equals(hash('sha256',$serverPublic),(string)($identity['server_key_id']??'')))throw new RuntimeException('DCP server signing identity is invalid.');$envelopes->trustDeviceSigningKey($serverDeviceId,$serverPublic,$deviceId);$signedTransport=true;}catch(Throwable $e){if(!str_contains($e->getMessage(),'DCP API error 404'))throw $e;fwrite(STDERR,"Warning: server does not support signed task envelopes; using legacy bearer-token transport.\n");}
if($workspaceOverride!==''){$workspace=$workspaceOverride;}else{$workspace=(new DeviceWorkspaceService($db,$config))->ensure($deviceId)['path'];}
$factory=require __DIR__.'/worker.php';$executor=$factory($workspace);
echo "DCP Device Agent started for ".$server."\n";echo "Device: ".$deviceId." · Workspace: ".$workspace."\n";
while(true){try{$heartbeat=api($server.'/api/device/heartbeat',$token,[]);if(($heartbeat['device_id']??'')!==$deviceId)throw new RuntimeException('Paired device identity changed during the agent session.');$d=api($server.'/api/device/tasks',$token);foreach($d['tasks']??[] as $task){$status='completed';$envelopeId=null;try{if($signedTransport){if(!is_array($task['signed_envelope']??null)||!is_string($task['signature']??null))throw new RuntimeException('Signed task envelope is missing from the server response.');$envelopeId=(string)($task['signed_envelope']['envelope_id']??'');$verified=$envelopes->verifyAndConsume($task['signed_envelope'],$task['signature'],$deviceId);if(($verified['task_id']??null)!==(string)$task['id'])throw new RuntimeException('Signed task envelope does not match the polled task ID.');$payload=$verified['payload'];$envelopeId=$verified['envelope_id'];}else{$payload=$task['payload']??[];}$result=$executor->execute($payload);}catch(Throwable $e){$status='failed';$result=['error'=>$e->getMessage()];} $body=['id'=>$task['id'],'status'=>$status,'result'=>$result];if($signedTransport&&$envelopeId!==null){$signedResult=['schema_version'=>1,'task_id'=>(string)$task['id'],'envelope_id'=>$envelopeId,'device_id'=>$deviceId,'status'=>$status,'result'=>$result,'completed_at'=>date(DATE_ATOM)];$body['signed_result']=$signedResult;$body['signature']=$envelopes->signPayload($deviceId,$signedResult);}api($server.'/api/device/task-result',$token,$body);echo date(DATE_ATOM).' '.$task['id'].' '.$status."\n";}}catch(Throwable $e){fwrite(STDERR,date(DATE_ATOM).' '.$e->getMessage()."\n");}if(getenv('DCP_AGENT_ONCE')==='1')break;sleep(10);}
